//! Only exact original layer3 images and twenty complete fixed ABI records.
use super::{CubinIo, CubinKernelManifest, CubinLaunchAttributes, VerifiedCubin, failure};
use cubecl_core::server::ServerError;
use sha2::{Digest, Sha256};
pub(super) fn digest(m: &CubinKernelManifest) -> [u8; 32] {
    let mut h = Sha256::new();
    h.update((m.entry.len() as u64).to_le_bytes());
    h.update(m.entry.as_bytes());
    h.update([m.binary_sm]);
    for v in m.grid.into_iter().chain(m.block) {
        h.update(v.to_le_bytes());
    }
    h.update(m.dynamic_shared_bytes.to_le_bytes());
    h.update([match m.attributes {
        CubinLaunchAttributes::None => 0,
        CubinLaunchAttributes::Unsupported => 1,
    }]);
    h.update((m.bindings.len() as u64).to_le_bytes());
    for b in &m.bindings {
        h.update(b.bytes.to_le_bytes());
        h.update(b.alignment.to_le_bytes());
        h.update([io(b.io)]);
    }
    h.update((m.parameters.len() as u64).to_le_bytes());
    for p in &m.parameters {
        h.update((p.offset as u64).to_le_bytes());
        h.update((p.template.len() as u64).to_le_bytes());
        h.update(&p.template);
    }
    h.update((m.fixups.len() as u64).to_le_bytes());
    for f in &m.fixups {
        for n in [
            f.parameter as u64,
            f.byte_offset as u64,
            f.binding as u64,
            f.binding_offset,
            f.extent,
            f.alignment,
        ] {
            h.update(n.to_le_bytes());
        }
        h.update([io(f.io)]);
    }
    h.finalize().into()
}
fn io(v: CubinIo) -> u8 {
    match v {
        CubinIo::Read => 0,
        CubinIo::Write => 1,
        CubinIo::ReadWrite => 2,
    }
}
pub(super) fn require(image: &VerifiedCubin, m: &CubinKernelManifest) -> Result<(), ServerError> {
    let actual = digest(m);
    if !RULES.iter().any(|(sha, bytes, sm, abi)| {
        image.sha256() == *sha
            && image.byte_len() == *bytes
            && image.binary_sm() == *sm
            && actual == *abi
    }) {
        return Err(failure(
            "closed first-attention exact image and complete source ABI",
        ));
    }
    if image.derived_from().is_none() && image.captured_from().is_none() {
        return Err(failure(
            "first-attention source image has no sealed provenance",
        ));
    }
    Ok(())
}
