// Only actual N1 final writers precede source's4096B output copy: first two
// unsplit mains and the last combine, never the split producer alone.
pub(crate) fn require_n1_copy(
    image: &VerifiedCubin,
    m: &CubinKernelManifest,
) -> Result<(), ServerError> {
    require(image, m)?;
    let abi = digest(m);
    if ![10usize, 11, 19]
        .into_iter()
        .any(|index| RULES[index].3 == abi)
    {
        return Err(failure(
            "attention copy only exact original final N1 FA records",
        ));
    }
    Ok(())
}

#[cfg(test)]
mod tests {
    use super::super::{CubinBinding, CubinParameter, CubinPointerFixup, CubinSetPolicy};
    use super::*;
    #[test]
    fn separate_attention_capacity_preserves_both_existing_scopes() {
        assert_eq!(RULES.len(), 20);
        let images = RULES
            .iter()
            .map(|r| r.0)
            .collect::<std::collections::BTreeSet<_>>();
        assert_eq!(images.len(), 9);
        assert!(
            CubinSetPolicy::FirstAttentionCaptured
                .limits(8, 12, 19, true, true)
                .is_ok()
        );
        for (m, f, r, nm, nf) in [
            (9, 12, 19, true, false),
            (8, 13, 19, false, true),
            (8, 12, 20, false, false),
            (10, 12, 0, false, false),
        ] {
            assert!(
                CubinSetPolicy::FirstAttentionCaptured
                    .limits(m, f, r, nm, nf)
                    .is_err()
            );
        }
        assert!(
            CubinSetPolicy::ProjectionSix
                .limits(6, 8, 19, false, false)
                .is_err()
        );
        assert!(
            CubinSetPolicy::ConnectedQwen08
                .limits(7, 12, 21, false, false)
                .is_err()
        );
    }
    #[test]
    fn complete_abi_digest_includes_scalars_geometry_ranges_and_io() {
        let m = CubinKernelManifest {
            entry: "source_fixture".into(),
            binary_sm: 86,
            grid: [1, 1, 1],
            block: [32, 1, 1],
            dynamic_shared_bytes: 0,
            attributes: CubinLaunchAttributes::None,
            bindings: vec![CubinBinding {
                bytes: 32,
                alignment: 16,
                io: CubinIo::Read,
            }],
            parameters: vec![CubinParameter {
                offset: 0,
                template: vec![0; 16],
            }],
            fixups: vec![CubinPointerFixup {
                parameter: 0,
                byte_offset: 0,
                binding: 0,
                binding_offset: 0,
                extent: 32,
                alignment: 16,
                io: CubinIo::Read,
            }],
        };
        let original = digest(&m);
        for kind in 0..13 {
            let mut x = m.clone();
            match kind {
                0 => x.entry.push('x'),
                1 => x.binary_sm = 80,
                2 => x.grid[0] = 2,
                3 => x.block[0] = 64,
                4 => x.dynamic_shared_bytes = 16,
                5 => x.attributes = CubinLaunchAttributes::Unsupported,
                6 => x.bindings[0].bytes = 64,
                7 => x.bindings[0].io = CubinIo::Write,
                8 => x.parameters[0].offset = 8,
                9 => x.parameters[0].template[12] = 1,
                10 => x.fixups[0].binding_offset = 16,
                11 => x.fixups[0].extent = 16,
                _ => x.fixups[0].io = CubinIo::Write,
            }
            assert_ne!(digest(&x), original, "field{kind}");
        }
        assert!(RULES.iter().all(|r| r.3 != original));
    }
}
